   178→/**
   179→ * Using the elevate system.
   180→ * Automatic contrast adjustment.
   181→ *
   182→ * <element className="hover-elevate" />
   183→ * <element className="active-elevate-2" />
   184→ *
   185→ * // Using the tailwind utility when a data attribute is "on"
   186→ * <element className="toggle-elevate data-[state=on]:toggle-elevated" />
   187→ * // Or manually controlling the toggle state
   188→ * <element className="toggle-elevate toggle-elevated" />
   189→ *
   190→ * Elevation systems have to handle many states.
   191→ * - not-hovered, vs. hovered vs. active  (three mutually exclusive states)
   192→ * - toggled or not
   193→ * - focused or not (this is not handled with these utilities)
   194→ *
   195→ * Even without handling focused or not, this is six possible combinations that
   196→ * need to be distinguished from eachother visually.
   197→ */
   198→@layer utilities {
   199→
   200→  /* Hide ugly search cancel button in Chrome until we can style it properly */
   201→  input[type="search"]::-webkit-search-cancel-button {
   202→    @apply hidden;
   203→  }
   204→
   205→  /* Placeholder styling for contentEditable div */
   206→  [contenteditable][data-placeholder]:empty::before {
   207→    content: attr(data-placeholder);
   208→    color: hsl(var(--muted-foreground));
   209→    pointer-events: none;
   210→  }
   211→
   212→  /* .no-default-hover-elevate/no-default-active-elevate is an escape hatch so consumers of
   213→   * buttons/badges can remove the automatic brightness adjustment on interactions
   214→   * and program their own. */
   215→  .no-default-hover-elevate {}
   216→
   217→  .no-default-active-elevate {}
   218→
   219→
   220→  /**
   221→   * Toggleable backgrounds go behind the content. Hoverable/active goes on top.
   222→   * This way they can stack/compound. Both will overlap the parent's borders!
   223→   * So borders will be automatically adjusted both on toggle, and hover/active,
   224→   * and they will be compounded.
   225→   */
   226→  .toggle-elevate::before,
   227→  .toggle-elevate-2::before {
   228→    content: "";
   229→    pointer-events: none;
   230→    position: absolute;
   231→    inset: 0px;
   232→    /*border-radius: inherit;   match rounded corners */
   233→    border-radius: inherit;
   234→    z-index: -1;
   235→    /* sits behind content but above backdrop */
   236→  }
   237→
   238→  .toggle-elevate.toggle-elevated::before {
   239→    background-color: var(--elevate-2);
   240→  }
   241→
   242→  /* If there's a 1px border, adjust the inset so that it covers that parent's border */
   243→  .border.toggle-elevate::before {
   244→    inset: -1px;
   245→  }
   246→
   247→  /* Does not work on elements with overflow:hidden! */
   248→  .hover-elevate:not(.no-default-hover-elevate),
   249→  .active-elevate:not(.no-default-active-elevate),
   250→  .hover-elevate-2:not(.no-default-hover-elevate),
   251→  .active-elevate-2:not(.no-default-active-elevate) {
   252→    position: relative;
   253→    z-index: 0;
   254→  }
   255→
   256→  .hover-elevate:not(.no-default-hover-elevate)::after,
   257→  .active-elevate:not(.no-default-active-elevate)::after,
   258→  .hover-elevate-2:not(.no-default-hover-elevate)::after,
   259→  .active-elevate-2:not(.no-default-active-elevate)::after {
   260→    content: "";
   261→    pointer-events: none;
   262→    position: absolute;
   263→    inset: 0px;
   264→    /*border-radius: inherit;   match rounded corners */
   265→    border-radius: inherit;
   266→    z-index: 999;
   267→    /* sits in front of content */
   268→  }
   269→
   270→  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
   271→  .active-elevate:active:not(.no-default-active-elevate)::after {
   272→    background-color: var(--elevate-1);
   273→  }
   274→
   275→  .hover-elevate-2:hover:not(.no-default-hover-elevate)::after,
   276→  .active-elevate-2:active:not(.no-default-active-elevate)::after {
   277→    background-color: var(--elevate-2);
   278→  }
   279→
   280→  /* If there's a 1px border, adjust the inset so that it covers that parent's border */
   281→  .border.hover-elevate:not(.no-hover-interaction-elevate)::after,
   282→  .border.active-elevate:not(.no-active-interaction-elevate)::after,
   283→  .border.hover-elevate-2:not(.no-hover-interaction-elevate)::after,
   284→  .border.active-elevate-2:not(.no-active-interaction-elevate)::after,
