import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { ImageUploader } from "@/components/image-uploader";
import { InvoiceEditor } from "@/components/invoice-editor";
import { InvoiceHistory } from "@/components/invoice-history";
import { InvoicePreview } from "@/components/invoice-preview";
import { ThemeToggle } from "@/components/theme-toggle";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import type { ExtractedItem, Invoice, InvoiceItem } from "@shared/schema";
import { FileText, Zap, History } from "lucide-react";
import { Button } from "@/components/ui/button";

type AppView = "upload" | "editor" | "preview" | "history";

export default function Home() {
  const [view, setView] = useState<AppView>("upload");
  const [extractedItems, setExtractedItems] = useState<ExtractedItem[]>([]);
  const [currentInvoice, setCurrentInvoice] = useState<(Invoice & { items: InvoiceItem[] }) | null>(null);
  const [invoiceNumber, setInvoiceNumber] = useState("INV-39");
  const { toast } = useToast();

  const invoiceNumberQuery = useQuery<{ invoiceNumber: string }>({
    queryKey: ["/api/invoice-number"],
  });

  const currentInvNum = invoiceNumberQuery.data?.invoiceNumber || invoiceNumber;

  const extractMutation = useMutation({
    mutationFn: async (formData: FormData) => {
      const res = await fetch("/api/extract", {
        method: "POST",
        body: formData,
      });
      if (!res.ok) throw new Error("Failed to extract data");
      return res.json();
    },
    onSuccess: (data) => {
      setExtractedItems(data.items || []);
      setView("editor");
      toast({
        title: "Extraction complete",
        description: `Found ${data.items?.length || 0} items in the image.`,
      });
    },
    onError: () => {
      toast({
        title: "Extraction failed",
        description: "Could not extract data from the image. Please try again.",
        variant: "destructive",
      });
    },
  });

  const saveMutation = useMutation({
    mutationFn: async (data: { items: ExtractedItem[]; totalAmount: number }) => {
      const res = await apiRequest("POST", "/api/invoices", {
        invoiceNumber: currentInvNum,
        clientName: "ART FASHION LLC",
        clientAddress: "Abu Dhabi, UAE",
        currency: "AED",
        totalAmount: data.totalAmount,
        items: data.items,
      });
      return res.json();
    },
    onSuccess: (data) => {
      setCurrentInvoice(data);
      setView("preview");
      queryClient.invalidateQueries({ queryKey: ["/api/invoices"] });
      queryClient.invalidateQueries({ queryKey: ["/api/invoice-number"] });
      toast({
        title: "Invoice saved",
        description: `Invoice ${data.invoiceNumber} has been created.`,
      });
    },
    onError: () => {
      toast({
        title: "Save failed",
        description: "Could not save the invoice. Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleImageUpload = (formData: FormData) => {
    extractMutation.mutate(formData);
  };

  const handleSaveInvoice = (items: ExtractedItem[]) => {
    const total = items.reduce((sum, item) => sum + item.quantity * item.rate, 0);
    saveMutation.mutate({ items, totalAmount: total });
  };

  const handleViewInvoice = async (invoice: Invoice) => {
    try {
      const res = await fetch(`/api/invoices/${invoice.id}`);
      if (!res.ok) throw new Error("Failed");
      const data = await res.json();
      setCurrentInvoice(data);
      setView("preview");
    } catch {
      toast({ title: "Error", description: "Could not load invoice.", variant: "destructive" });
    }
  };

  return (
    <div className="min-h-screen bg-background">
      <header className="sticky top-0 z-50 border-b bg-background/80 backdrop-blur-md">
        <div className="mx-auto max-w-6xl flex items-center justify-between gap-2 px-4 py-3">
          <div className="flex items-center gap-2">
            <div className="flex items-center justify-center w-9 h-9 rounded-md bg-primary">
              <Zap className="w-5 h-5 text-primary-foreground" />
            </div>
            <div>
              <h1 className="text-lg font-semibold leading-tight" data-testid="text-app-title">Digitizer</h1>
              <p className="text-xs text-muted-foreground leading-tight">Bazaar Note to Invoice</p>
            </div>
          </div>
          <div className="flex items-center gap-1">
            <Button
              variant={view === "upload" ? "secondary" : "ghost"}
              size="sm"
              onClick={() => { setView("upload"); setExtractedItems([]); setCurrentInvoice(null); }}
              data-testid="button-new-scan"
            >
              <Zap className="w-4 h-4 mr-1" />
              New Scan
            </Button>
            <Button
              variant={view === "history" ? "secondary" : "ghost"}
              size="sm"
              onClick={() => setView("history")}
              data-testid="button-history"
            >
              <History className="w-4 h-4 mr-1" />
              History
            </Button>
            <ThemeToggle />
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-6xl px-4 py-6">
        {view === "upload" && (
          <ImageUploader
            onUpload={handleImageUpload}
            isLoading={extractMutation.isPending}
          />
        )}

        {view === "editor" && (
          <InvoiceEditor
            items={extractedItems}
            invoiceNumber={currentInvNum}
            onSave={handleSaveInvoice}
            onBack={() => setView("upload")}
            isSaving={saveMutation.isPending}
          />
        )}

        {view === "preview" && currentInvoice && (
          <InvoicePreview
            invoice={currentInvoice}
            onBack={() => setView("editor")}
            onNewScan={() => { setView("upload"); setExtractedItems([]); setCurrentInvoice(null); }}
          />
        )}

        {view === "history" && (
          <InvoiceHistory
            onViewInvoice={handleViewInvoice}
          />
        )}
      </main>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Moon, Sun } from "lucide-react";
import { Button } from "@/components/ui/button";

export function ThemeToggle() {
  const [dark, setDark] = useState(() => {
    if (typeof window !== "undefined") {
      return localStorage.getItem("theme") === "dark" ||
        (!localStorage.getItem("theme") && window.matchMedia("(prefers-color-scheme: dark)").matches);
    }
    return true;
  });

  useEffect(() => {
    document.documentElement.classList.toggle("dark", dark);
    localStorage.setItem("theme", dark ? "dark" : "light");
  }, [dark]);

  return (
    <Button
      size="icon"
      variant="ghost"
      onClick={() => setDark(!dark)}
      data-testid="button-theme-toggle"
    >
      {dark ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
    </Button>
  );
}

import { useState, useRef, useCallback } from "react";
import { Upload, Camera, Image, Loader2, FileImage } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";

interface ImageUploaderProps {
  onUpload: (formData: FormData) => void;
  isLoading: boolean;
}

export function ImageUploader({ onUpload, isLoading }: ImageUploaderProps) {
  const [preview, setPreview] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  const handleFile = useCallback((file: File) => {
    if (!file.type.startsWith("image/")) return;
    const reader = new FileReader();
    reader.onload = (e) => setPreview(e.target?.result as string);
    reader.readAsDataURL(file);

    const formData = new FormData();
    formData.append("image", file);
    onUpload(formData);
  }, [onUpload]);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files[0];
    if (file) handleFile(file);
  }, [handleFile]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) handleFile(file);
  };

  return (
    <div className="flex flex-col items-center gap-8">
      <div className="text-center space-y-3 max-w-lg">
        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-primary/10 mb-2">
          <FileImage className="w-8 h-8 text-primary" />
        </div>
        <h2 className="text-2xl font-semibold" data-testid="text-upload-title">
          Upload Bazaar Note
        </h2>
        <p className="text-muted-foreground text-sm leading-relaxed">
          Take a photo or upload an image of a handwritten bazaar note. The AI will extract quantities, model numbers, and rates automatically.
        </p>
      </div>

      <Card
        className={`w-full max-w-xl p-0 transition-colors ${
          dragOver ? "border-primary bg-primary/5" : ""
        }`}
      >
        <div
          className="relative flex flex-col items-center justify-center gap-4 p-10 cursor-pointer min-h-[280px]"
          onDrop={handleDrop}
          onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
          onDragLeave={() => setDragOver(false)}
          onClick={() => fileInputRef.current?.click()}
          data-testid="dropzone-upload"
        >
          {isLoading ? (
            <div className="flex flex-col items-center gap-4">
              <div className="relative">
                <div className="w-20 h-20 rounded-full border-4 border-muted animate-pulse" />
                <Loader2 className="w-10 h-10 text-primary absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-spin" />
              </div>
              <div className="text-center">
                <p className="font-medium" data-testid="text-processing">Processing image...</p>
                <p className="text-sm text-muted-foreground mt-1">AI is extracting bazaar data</p>
              </div>
            </div>
          ) : preview ? (
            <div className="flex flex-col items-center gap-3">
              <img
                src={preview}
                alt="Preview"
                className="max-h-48 rounded-md object-contain"
                data-testid="img-preview"
              />
              <p className="text-sm text-muted-foreground">Click or drop another image to replace</p>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-3">
              <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center">
                <Upload className="w-7 h-7 text-muted-foreground" />
              </div>
              <div className="text-center">
                <p className="font-medium">Drop your bazaar note here</p>
                <p className="text-sm text-muted-foreground mt-1">or click to browse files</p>
              </div>
              <div className="flex items-center gap-2 mt-2 text-xs text-muted-foreground">
                <Image className="w-3.5 h-3.5" />
                <span>JPG, PNG, WEBP supported</span>
              </div>
            </div>
          )}

          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            className="hidden"
            onChange={handleFileChange}
            data-testid="input-file-upload"
          />
        </div>
      </Card>

      <div className="flex items-center gap-3">
        <Button
          variant="secondary"
          onClick={() => cameraInputRef.current?.click()}
          disabled={isLoading}
          data-testid="button-camera"
        >
          <Camera className="w-4 h-4 mr-2" />
          Take Photo
        </Button>
        <input
          ref={cameraInputRef}
          type="file"
          accept="image/*"
          capture="environment"
          className="hidden"
          onChange={handleFileChange}
        />
      </div>

      <Card className="w-full max-w-xl p-5">
        <h3 className="text-sm font-medium mb-3">How it works</h3>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          {[
            { step: "1", title: "Upload", desc: "Photo of handwritten note" },
            { step: "2", title: "Extract", desc: "AI reads Qty, Model, Rate" },
            { step: "3", title: "Invoice", desc: "Generate professional PDF" },
          ].map((item) => (
            <div key={item.step} className="flex items-start gap-3">
              <div className="flex-shrink-0 w-7 h-7 rounded-full bg-primary/10 text-primary flex items-center justify-center text-xs font-semibold">
                {item.step}
              </div>
              <div>
                <p className="text-sm font-medium">{item.title}</p>
                <p className="text-xs text-muted-foreground">{item.desc}</p>
              </div>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import { Trash2, Plus, ArrowLeft, Save, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import type { ExtractedItem } from "@shared/schema";

interface InvoiceEditorProps {
  items: ExtractedItem[];
  invoiceNumber: string;
  onSave: (items: ExtractedItem[]) => void;
  onBack: () => void;
  isSaving: boolean;
}

export function InvoiceEditor({ items: initialItems, invoiceNumber, onSave, onBack, isSaving }: InvoiceEditorProps) {
  const [items, setItems] = useState<ExtractedItem[]>(initialItems);

  useEffect(() => {
    setItems(initialItems);
  }, [initialItems]);

  const total = items.reduce((sum, item) => sum + item.quantity * item.rate, 0);

  const updateItem = useCallback((index: number, field: keyof ExtractedItem, value: string | number | boolean) => {
    setItems(prev => {
      const updated = [...prev];
      updated[index] = { ...updated[index], [field]: value };
      if (field === "quantity" || field === "rate") {
        updated[index].amount = Number(updated[index].quantity) * Number(updated[index].rate);
      }
      if (field === "description" || field === "quantity" || field === "rate") {
        updated[index].isUncertain = false;
      }
      return updated;
    });
  }, []);

  const removeItem = useCallback((index: number) => {
    setItems(prev => prev.filter((_, i) => i !== index));
  }, []);

  const addItem = useCallback(() => {
    setItems(prev => [...prev, {
      description: "MX- MOD.no",
      quantity: 0,
      rate: 0,
      amount: 0,
      isUncertain: false,
    }]);
  }, []);

  const uncertainCount = items.filter(i => i.isUncertain).length;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="icon" onClick={onBack} data-testid="button-back-to-upload">
            <ArrowLeft className="w-4 h-4" />
          </Button>
          <div>
            <h2 className="text-xl font-semibold" data-testid="text-editor-title">Edit Extracted Data</h2>
            <p className="text-sm text-muted-foreground">
              Invoice <span className="font-mono font-medium">{invoiceNumber}</span>
              {" "} &middot; ART FASHION LLC
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {uncertainCount > 0 && (
            <Badge variant="destructive" data-testid="badge-uncertain-count">
              <AlertTriangle className="w-3 h-3 mr-1" />
              {uncertainCount} uncertain
            </Badge>
          )}
          <Button onClick={() => onSave(items)} disabled={isSaving || items.length === 0} data-testid="button-save-invoice">
            <Save className="w-4 h-4 mr-2" />
            {isSaving ? "Saving..." : "Save & Preview"}
          </Button>
        </div>
      </div>

      <Card className="p-0">
        <div className="overflow-x-auto">
          <table className="w-full" data-testid="table-invoice-items">
            <thead>
              <tr className="border-b bg-muted/30">
                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-3 w-8">#</th>
                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-3">Description</th>
                <th className="text-right text-xs font-medium text-muted-foreground px-4 py-3 w-24">Qty</th>
                <th className="text-right text-xs font-medium text-muted-foreground px-4 py-3 w-28">Rate (AED)</th>
                <th className="text-right text-xs font-medium text-muted-foreground px-4 py-3 w-28">Amount (AED)</th>
                <th className="text-center text-xs font-medium text-muted-foreground px-4 py-3 w-12"></th>
              </tr>
            </thead>
            <tbody>
              {items.map((item, index) => (
                <tr
                  key={index}
                  className={`border-b last:border-b-0 transition-colors ${
                    item.isUncertain ? "bg-destructive/5" : ""
                  }`}
                  data-testid={`row-item-${index}`}
                >
                  <td className="px-4 py-2 text-sm text-muted-foreground">{index + 1}</td>
                  <td className="px-4 py-2">
                    <div className="flex items-center gap-2">
                      <Input
                        value={item.description.includes("[???]") ? "" : item.description}
                        placeholder={item.isUncertain ? "[???] Uncertain value" : "MX-XXXX MOD.no"}
                        onChange={(e) => updateItem(index, "description", e.target.value)}
                        className={`h-8 text-sm font-mono ${
                          item.isUncertain ? "border-destructive/50 text-destructive placeholder:text-destructive/60" : ""
                        }`}
                        data-testid={`input-description-${index}`}
                      />
                      {item.isUncertain && (
                        <AlertTriangle className="w-4 h-4 text-destructive flex-shrink-0" />
                      )}
                    </div>
                  </td>
                  <td className="px-4 py-2">
                    <Input
                      type="number"
                      value={item.quantity || ""}
                      placeholder="0"
                      onChange={(e) => updateItem(index, "quantity", Number(e.target.value))}
                      className={`h-8 text-sm text-right ${
                        item.isUncertain ? "border-destructive/50" : ""
                      }`}
                      data-testid={`input-quantity-${index}`}
                    />
                  </td>
                  <td className="px-4 py-2">
                    <Input
                      type="number"
                      value={item.rate || ""}
                      placeholder="0"
                      onChange={(e) => updateItem(index, "rate", Number(e.target.value))}
                      className={`h-8 text-sm text-right ${
                        item.isUncertain ? "border-destructive/50" : ""
                      }`}
                      data-testid={`input-rate-${index}`}
                    />
                  </td>
                  <td className="px-4 py-2 text-right">
                    <span className="text-sm font-medium font-mono" data-testid={`text-amount-${index}`}>
                      {(item.quantity * item.rate).toFixed(2)}
                    </span>
                  </td>
                  <td className="px-4 py-2 text-center">
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => removeItem(index)}
                      className="h-7 w-7 text-muted-foreground"
                      data-testid={`button-delete-${index}`}
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </Button>
                  </td>
                </tr>
              ))}
              {items.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-4 py-10 text-center text-sm text-muted-foreground">
                    No items extracted. Add items manually or try uploading again.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        <div className="border-t px-4 py-3 flex items-center justify-between gap-2">
          <Button variant="ghost" size="sm" onClick={addItem} data-testid="button-add-item">
            <Plus className="w-4 h-4 mr-1" />
            Add Item
          </Button>
          <div className="flex items-center gap-4">
            <span className="text-sm text-muted-foreground">Total AED</span>
            <span className="text-xl font-bold font-mono" data-testid="text-total-amount">
              {total.toFixed(2)}
            </span>
          </div>
        </div>
      </Card>
    </div>
  );
}

import { useCallback } from "react";
import { ArrowLeft, Download, Plus, FileText } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import type { Invoice, InvoiceItem } from "@shared/schema";

interface InvoicePreviewProps {
  invoice: Invoice & { items: InvoiceItem[] };
  onBack: () => void;
  onNewScan: () => void;
}

export function InvoicePreview({ invoice, onBack, onNewScan }: InvoicePreviewProps) {
  const total = invoice.items.reduce((sum, item) => sum + item.quantity * item.rate, 0);

  const generatePDF = useCallback(async () => {
    const { jsPDF } = await import("jspdf");
    const autoTable = (await import("jspdf-autotable")).default;

    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();

    doc.setFillColor(20, 30, 48);
    doc.rect(0, 0, pageWidth, 50, "F");

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    doc.text("INVOICE", 20, 25);

    doc.setFontSize(12);
    doc.setFont("helvetica", "normal");
    doc.text(invoice.invoiceNumber, 20, 35);

    doc.setFontSize(10);
    doc.text(`Date: ${new Date(invoice.createdAt).toLocaleDateString("en-GB")}`, pageWidth - 20, 25, { align: "right" });
    doc.text(`Currency: ${invoice.currency}`, pageWidth - 20, 35, { align: "right" });

    doc.setTextColor(50, 50, 50);
    doc.setFontSize(11);
    doc.setFont("helvetica", "bold");
    doc.text("Bill To:", 20, 62);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.text(invoice.clientName, 20, 70);
    doc.text(invoice.clientAddress, 20, 77);

    doc.setFont("helvetica", "bold");
    doc.text("From:", pageWidth - 80, 62);
    doc.setFont("helvetica", "normal");
    doc.text("Digitizer", pageWidth - 80, 70);
    doc.text("Islamabad, Pakistan", pageWidth - 80, 77);

    const tableData = invoice.items.map((item, i) => [
      (i + 1).toString(),
      item.description,
      item.quantity.toString(),
      item.rate.toFixed(2),
      (item.quantity * item.rate).toFixed(2),
    ]);

    autoTable(doc, {
      startY: 90,
      head: [["#", "Description", "Qty", "Rate (AED)", "Amount (AED)"]],
      body: tableData,
      theme: "grid",
      headStyles: {
        fillColor: [20, 30, 48],
        textColor: [255, 255, 255],
        fontSize: 9,
        fontStyle: "bold",
      },
      bodyStyles: {
        fontSize: 9,
        textColor: [50, 50, 50],
      },
      alternateRowStyles: {
        fillColor: [245, 247, 250],
      },
      columnStyles: {
        0: { cellWidth: 12, halign: "center" },
        1: { cellWidth: "auto" },
        2: { cellWidth: 20, halign: "right" },
        3: { cellWidth: 30, halign: "right" },
        4: { cellWidth: 35, halign: "right" },
      },
      margin: { left: 20, right: 20 },
    });

    const finalY = (doc as any).lastAutoTable?.finalY || 150;

    doc.setFillColor(245, 247, 250);
    doc.rect(pageWidth - 90, finalY + 10, 70, 25, "F");
    doc.setFont("helvetica", "bold");
    doc.setFontSize(10);
    doc.setTextColor(50, 50, 50);
    doc.text("Total AED", pageWidth - 85, finalY + 22);
    doc.setFontSize(14);
    doc.setTextColor(20, 30, 48);
    doc.text(total.toFixed(2), pageWidth - 25, finalY + 30, { align: "right" });

    doc.setDrawColor(200, 200, 200);
    doc.line(20, finalY + 50, pageWidth - 20, finalY + 50);
    doc.setFontSize(8);
    doc.setTextColor(150, 150, 150);
    doc.setFont("helvetica", "normal");
    doc.text("Generated by Digitizer - Bazaar Note to Invoice", pageWidth / 2, finalY + 58, { align: "center" });

    doc.save(`${invoice.invoiceNumber}.pdf`);
  }, [invoice, total]);

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="icon" onClick={onBack} data-testid="button-back-to-editor">
            <ArrowLeft className="w-4 h-4" />
          </Button>
          <div>
            <h2 className="text-xl font-semibold" data-testid="text-preview-title">Invoice Preview</h2>
            <p className="text-sm text-muted-foreground">
              <span className="font-mono font-medium">{invoice.invoiceNumber}</span>
              {" "} &middot; {invoice.clientName}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="secondary" onClick={onNewScan} data-testid="button-new-scan-preview">
            <Plus className="w-4 h-4 mr-2" />
            New Scan
          </Button>
          <Button onClick={generatePDF} data-testid="button-generate-pdf">
            <Download className="w-4 h-4 mr-2" />
            Generate PDF
          </Button>
        </div>
      </div>

      <Card className="p-6 max-w-3xl mx-auto">
        <div className="space-y-6">
          <div className="flex items-start justify-between gap-4">
            <div>
              <div className="flex items-center gap-2 mb-1">
                <FileText className="w-5 h-5 text-primary" />
                <h3 className="text-lg font-bold">INVOICE</h3>
              </div>
              <p className="font-mono text-sm text-muted-foreground">{invoice.invoiceNumber}</p>
            </div>
            <div className="text-right">
              <Badge variant="secondary" data-testid="badge-status">{invoice.status}</Badge>
              <p className="text-xs text-muted-foreground mt-1">
                {new Date(invoice.createdAt).toLocaleDateString("en-GB", {
                  day: "2-digit",
                  month: "short",
                  year: "numeric",
                })}
              </p>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-6">
            <div>
              <p className="text-xs text-muted-foreground mb-1 uppercase tracking-wider">Bill To</p>
              <p className="font-medium text-sm">{invoice.clientName}</p>
              <p className="text-sm text-muted-foreground">{invoice.clientAddress}</p>
            </div>
            <div className="text-right">
              <p className="text-xs text-muted-foreground mb-1 uppercase tracking-wider">From</p>
              <p className="font-medium text-sm">Digitizer</p>
              <p className="text-sm text-muted-foreground">Islamabad, Pakistan</p>
            </div>
          </div>

          <div className="border rounded-md">
            <table className="w-full" data-testid="table-preview-items">
              <thead>
                <tr className="bg-muted/30 border-b">
                  <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 w-8">#</th>
                  <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5">Description</th>
                  <th className="text-right text-xs font-medium text-muted-foreground px-4 py-2.5 w-16">Qty</th>
                  <th className="text-right text-xs font-medium text-muted-foreground px-4 py-2.5 w-24">Rate</th>
                  <th className="text-right text-xs font-medium text-muted-foreground px-4 py-2.5 w-28">Amount</th>
                </tr>
              </thead>
              <tbody>
                {invoice.items.map((item, i) => (
                  <tr key={item.id} className="border-b last:border-b-0" data-testid={`row-preview-${i}`}>
                    <td className="px-4 py-2.5 text-sm text-muted-foreground">{i + 1}</td>
                    <td className="px-4 py-2.5 text-sm font-mono font-medium">{item.description}</td>
                    <td className="px-4 py-2.5 text-sm text-right">{item.quantity}</td>
                    <td className="px-4 py-2.5 text-sm text-right font-mono">{item.rate.toFixed(2)}</td>
                    <td className="px-4 py-2.5 text-sm text-right font-mono font-medium">
                      {(item.quantity * item.rate).toFixed(2)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="flex justify-end">
            <div className="bg-muted/30 rounded-md px-5 py-3 min-w-[180px]">
              <div className="flex items-center justify-between gap-4">
                <span className="text-sm text-muted-foreground">Total {invoice.currency}</span>
                <span className="text-xl font-bold font-mono" data-testid="text-preview-total">
                  {total.toFixed(2)}
                </span>
              </div>
            </div>
          </div>
        </div>
      </Card>
    </div>
  );
}

import { useQuery, useMutation } from "@tanstack/react-query";
import { Trash2, Eye, FileText, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import type { Invoice } from "@shared/schema";

interface InvoiceHistoryProps {
  onViewInvoice: (invoice: Invoice) => void;
}

export function InvoiceHistory({ onViewInvoice }: InvoiceHistoryProps) {
  const { toast } = useToast();

  const { data: invoices, isLoading } = useQuery<Invoice[]>({
    queryKey: ["/api/invoices"],
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: number) => {
      await apiRequest("DELETE", `/api/invoices/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/invoices"] });
      queryClient.invalidateQueries({ queryKey: ["/api/invoice-number"] });
      toast({ title: "Invoice deleted" });
    },
  });

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-20 gap-3">
        <Loader2 className="w-8 h-8 text-muted-foreground animate-spin" />
        <p className="text-sm text-muted-foreground">Loading invoices...</p>
      </div>
    );
  }

  if (!invoices || invoices.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-20 gap-4">
        <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center">
          <FileText className="w-7 h-7 text-muted-foreground" />
        </div>
        <div className="text-center">
          <p className="font-medium" data-testid="text-no-invoices">No invoices yet</p>
          <p className="text-sm text-muted-foreground mt-1">
            Upload a bazaar note to create your first invoice.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div>
        <h2 className="text-xl font-semibold" data-testid="text-history-title">Invoice History</h2>
        <p className="text-sm text-muted-foreground">{invoices.length} invoice{invoices.length !== 1 ? "s" : ""}</p>
      </div>

      <div className="grid gap-3">
        {invoices.map((invoice) => (
          <Card
            key={invoice.id}
            className="p-4 hover-elevate cursor-pointer"
            onClick={() => onViewInvoice(invoice)}
            data-testid={`card-invoice-${invoice.id}`}
          >
            <div className="flex items-center justify-between gap-3">
              <div className="flex items-center gap-3 min-w-0">
                <div className="flex-shrink-0 w-10 h-10 rounded-md bg-primary/10 flex items-center justify-center">
                  <FileText className="w-5 h-5 text-primary" />
                </div>
                <div className="min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <p className="font-mono font-medium text-sm" data-testid={`text-invoice-number-${invoice.id}`}>
                      {invoice.invoiceNumber}
                    </p>
                    <Badge variant="secondary" className="text-xs">
                      {invoice.status}
                    </Badge>
                  </div>
                  <div className="flex items-center gap-2 mt-0.5">
                    <p className="text-xs text-muted-foreground">{invoice.clientName}</p>
                    <span className="text-xs text-muted-foreground">&middot;</span>
                    <p className="text-xs text-muted-foreground">
                      {new Date(invoice.createdAt).toLocaleDateString("en-GB", {
                        day: "2-digit",
                        month: "short",
                        year: "numeric",
                      })}
                    </p>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <div className="text-right">
                  <p className="font-mono font-bold text-sm" data-testid={`text-invoice-total-${invoice.id}`}>
                    AED {invoice.totalAmount.toFixed(2)}
                  </p>
                </div>
                <div className="flex items-center gap-1">
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={(e) => { e.stopPropagation(); onViewInvoice(invoice); }}
                    data-testid={`button-view-${invoice.id}`}
                  >
                    <Eye className="w-4 h-4" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={(e) => { e.stopPropagation(); deleteMutation.mutate(invoice.id); }}
                    className="text-muted-foreground"
                    data-testid={`button-delete-invoice-${invoice.id}`}
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}

import { Switch, Route } from "wouter";
import { queryClient } from "./lib/queryClient";
import { QueryClientProvider } from "@tanstack/react-query";
import { Toaster } from "@/components/ui/toaster";
import { TooltipProvider } from "@/components/ui/tooltip";
import NotFound from "@/pages/not-found";
import Home from "@/pages/home";

function Router() {
  return (
    <Switch>
      <Route path="/" component={Home} />
      <Route component={NotFound} />
    </Switch>
  );
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <TooltipProvider>
        <Toaster />
        <Router />
      </TooltipProvider>
    </QueryClientProvider>
  );
}

export default App;

