import type { Express } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import OpenAI from "openai";
import multer from "multer";

const openai = new OpenAI({
  apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
  baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
});

const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 10 * 1024 * 1024 } });

export async function registerRoutes(
  httpServer: Server,
  app: Express
): Promise<Server> {

  app.get("/api/invoices", async (_req, res) => {
    try {
      const invoiceList = await storage.getInvoices();
      res.json(invoiceList);
    } catch (error) {
      console.error("Error fetching invoices:", error);
      res.status(500).json({ error: "Failed to fetch invoices" });
    }
  });

  app.get("/api/invoices/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const invoice = await storage.getInvoice(id);
      if (!invoice) return res.status(404).json({ error: "Invoice not found" });
      const items = await storage.getInvoiceItems(id);
      res.json({ ...invoice, items });
    } catch (error) {
      console.error("Error fetching invoice:", error);
      res.status(500).json({ error: "Failed to fetch invoice" });
    }
  });

  app.post("/api/invoices", async (req, res) => {
    try {
      const invoiceNumber = await storage.getNextInvoiceNumber();
      const invoice = await storage.createInvoice({
        invoiceNumber,
        clientName: req.body.clientName || "ART FASHION LLC",
        clientAddress: req.body.clientAddress || "Abu Dhabi, UAE",
        currency: req.body.currency || "AED",
        totalAmount: req.body.totalAmount || 0,
        status: "draft",
        imageUrl: req.body.imageUrl || null,
      });

      if (req.body.items && Array.isArray(req.body.items)) {
        for (const item of req.body.items) {
          await storage.createInvoiceItem({
            invoiceId: invoice.id,
            description: item.description,
            quantity: 1,
            rate: item.rate,
            amount: item.amount ?? item.rate,
            isUncertain: item.isUncertain ? 1 : 0,
          });
        }
      }

      const items = await storage.getInvoiceItems(invoice.id);
      res.status(201).json({ ...invoice, items });
    } catch (error) {
      console.error("Error creating invoice:", error);
      res.status(500).json({ error: "Failed to create invoice" });
    }
  });

  app.put("/api/invoices/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const updated = await storage.updateInvoice(id, {
        clientName: req.body.clientName,
        clientAddress: req.body.clientAddress,
        totalAmount: req.body.totalAmount,
        status: req.body.status,
      });
      if (!updated) return res.status(404).json({ error: "Invoice not found" });

      if (req.body.items && Array.isArray(req.body.items)) {
        await storage.deleteInvoiceItems(id);
        for (const item of req.body.items) {
          await storage.createInvoiceItem({
            invoiceId: id,
            description: item.description,
            quantity: 1,
            rate: item.rate,
            amount: item.amount ?? item.rate,
            isUncertain: item.isUncertain ? 1 : 0,
          });
        }
      }

      const items = await storage.getInvoiceItems(id);
      res.json({ ...updated, items });
    } catch (error) {
      console.error("Error updating invoice:", error);
      res.status(500).json({ error: "Failed to update invoice" });
    }
  });

  app.delete("/api/invoices/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      await storage.deleteInvoice(id);
      res.status(204).send();
    } catch (error) {
      console.error("Error deleting invoice:", error);
      res.status(500).json({ error: "Failed to delete invoice" });
    }
  });

  app.post("/api/extract", upload.single("image"), async (req, res) => {
    try {
      if (!req.file) {
        return res.status(400).json({ error: "No image uploaded" });
      }

      const base64Image = req.file.buffer.toString("base64");
      const mimeType = req.file.mimetype || "image/jpeg";

      const response = await openai.chat.completions.create({
        model: "gpt-5.2",
        messages: [
          {
            role: "system",
            content: `You are an OCR specialist that extracts data from handwritten invoice/bazaar notes.

CRITICAL RULES — follow these exactly:

1. TOTAL LINE: The VERY LAST number/amount written in the note is the GRAND TOTAL for the whole invoice. Do NOT include it as a line item — it belongs only in the "grandTotal" field. Even if the last line looks like an item, it is the total.

2. NO QUANTITY: There is no separate quantity column. Every item has quantity = 1. Do NOT extract or invent quantities. The "amount" for each item equals its "rate".

3. DESCRIPTIONS: Preserve the description exactly as written. If a model number appears (like 4495, 45042, MX-44921 etc.), keep it as-is. Do not add or change prefixes unless already present.

4. UNCERTAIN VALUES: If any description or rate is hard to read or ambiguous, set isUncertain: true for that item.

5. LAST NUMBER IS TOTAL: Re-emphasize — if the note has 9 items followed by a number like "540.00" or "540", that final number is the SubTotal/Grand Total. Do not list it as item 10.

Return ONLY valid JSON in this exact format:
{
  "items": [
    { "description": "string", "rate": number, "amount": number, "isUncertain": boolean }
  ],
  "grandTotal": number
}

Example: A note with lines "MX-4495 40.00", "SIT 25.00", "45042 60.00", and then "125.00" at the end should produce:
{
  "items": [
    { "description": "MX-4495", "rate": 40.00, "amount": 40.00, "isUncertain": false },
    { "description": "SIT", "rate": 25.00, "amount": 25.00, "isUncertain": false },
    { "description": "45042", "rate": 60.00, "amount": 60.00, "isUncertain": false }
  ],
  "grandTotal": 125.00
}`
          },
          {
            role: "user",
            content: [
              {
                type: "text",
                text: "Extract all items from this handwritten invoice note. Remember: the LAST number is the grand total, not a line item. Return the data as JSON."
              },
              {
                type: "image_url",
                image_url: {
                  url: `data:${mimeType};base64,${base64Image}`
                }
              }
            ]
          }
        ],
        response_format: { type: "json_object" },
        max_completion_tokens: 8192,
      });

      const content = response.choices[0]?.message?.content || "{}";
      let parsed: any;
      try {
        parsed = JSON.parse(content);
      } catch {
        parsed = { items: [], grandTotal: 0 };
      }

      const items = (parsed.items || []).map((item: any) => ({
        description: String(item.description || "[???]"),
        quantity: 1,
        rate: Number(item.rate) || 0,
        amount: Number(item.amount) || Number(item.rate) || 0,
        isUncertain: Boolean(item.isUncertain),
      }));

      const grandTotal = Number(parsed.grandTotal) || items.reduce((s: number, i: any) => s + i.amount, 0);

      res.json({ items, grandTotal });
    } catch (error) {
      console.error("Error extracting data:", error);
      res.status(500).json({ error: "Failed to extract data from image" });
    }
  });

  app.get("/api/invoice-number", async (_req, res) => {
    try {
      const number = await storage.getNextInvoiceNumber();
      res.json({ invoiceNumber: number });
    } catch (error) {
      res.status(500).json({ error: "Failed to get invoice number" });
    }
  });

  return httpServer;
}

import { useState, useEffect, useCallback } from "react";
import { Trash2, Plus, ArrowLeft, Save, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import type { ExtractedItem } from "@shared/schema";

interface InvoiceEditorProps {
  items: ExtractedItem[];
  invoiceNumber: string;
  grandTotal?: number;
  onSave: (items: ExtractedItem[], grandTotal: number) => void;
  onBack: () => void;
  isSaving: boolean;
}

export function InvoiceEditor({ items: initialItems, invoiceNumber, grandTotal: initialGrandTotal, onSave, onBack, isSaving }: InvoiceEditorProps) {
  const [items, setItems] = useState<ExtractedItem[]>(initialItems);

  useEffect(() => {
    setItems(initialItems);
  }, [initialItems]);

  const computedTotal = items.reduce((sum, item) => sum + (item.amount ?? item.rate), 0);
  const total = initialGrandTotal && initialGrandTotal > 0 ? initialGrandTotal : computedTotal;

  const updateItem = useCallback((index: number, field: keyof ExtractedItem, value: string | number | boolean) => {
    setItems(prev => {
      const updated = [...prev];
      updated[index] = { ...updated[index], [field]: value };
      if (field === "rate") {
        updated[index].amount = Number(value);
        updated[index].quantity = 1;
      }
      if (field === "description" || field === "rate") {
        updated[index].isUncertain = false;
      }
      return updated;
    });
  }, []);

  const removeItem = useCallback((index: number) => {
    setItems(prev => prev.filter((_, i) => i !== index));
  }, []);

  const addItem = useCallback(() => {
    setItems(prev => [...prev, {
      description: "",
      quantity: 1,
      rate: 0,
      amount: 0,
      isUncertain: false,
    }]);
  }, []);

  const uncertainCount = items.filter(i => i.isUncertain).length;
  const saveTotal = items.reduce((sum, item) => sum + (item.amount ?? item.rate), 0);

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="icon" onClick={onBack} data-testid="button-back-to-upload">
            <ArrowLeft className="w-4 h-4" />
          </Button>
          <div>
            <h2 className="text-xl font-semibold" data-testid="text-editor-title">Edit Extracted Data</h2>
            <p className="text-sm text-muted-foreground">
              Invoice <span className="font-mono font-medium">{invoiceNumber}</span>
              {" "}&middot; ART FASHION LLC
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {uncertainCount > 0 && (
            <Badge variant="destructive" data-testid="badge-uncertain-count">
              <AlertTriangle className="w-3 h-3 mr-1" />
              {uncertainCount} uncertain
            </Badge>
          )}
          <Button onClick={() => onSave(items, saveTotal)} disabled={isSaving || items.length === 0} data-testid="button-save-invoice">
            <Save className="w-4 h-4 mr-2" />
            {isSaving ? "Saving..." : "Save & Preview"}
          </Button>
        </div>
      </div>

      <Card className="p-0">
        <div className="overflow-x-auto">
          <table className="w-full" data-testid="table-invoice-items">
            <thead>
              <tr className="border-b bg-muted/30">
                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-3 w-8">#</th>
                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-3">Description</th>
                <th className="text-right text-xs font-medium text-muted-foreground px-4 py-3 w-32">Rate (AED)</th>
                <th className="text-right text-xs font-medium text-muted-foreground px-4 py-3 w-32">Amount (AED)</th>
                <th className="text-center text-xs font-medium text-muted-foreground px-4 py-3 w-12"></th>
              </tr>
            </thead>
            <tbody>
              {items.map((item, index) => (
                <tr
                  key={index}
                  className={`border-b last:border-b-0 transition-colors ${item.isUncertain ? "bg-destructive/5" : ""}`}
                  data-testid={`row-item-${index}`}
                >
                  <td className="px-4 py-2 text-sm text-muted-foreground">{index + 1}</td>
                  <td className="px-4 py-2">
                    <div className="flex items-center gap-2">
                      <Input
                        value={item.description.includes("[???]") ? "" : item.description}
                        placeholder={item.isUncertain ? "[???] Uncertain — please verify" : "Item description"}
                        onChange={(e) => updateItem(index, "description", e.target.value)}
                        className={`h-8 text-sm font-mono ${item.isUncertain ? "border-destructive/50 text-destructive placeholder:text-destructive/60" : ""}`}
                        data-testid={`input-description-${index}`}
                      />
                      {item.isUncertain && (
                        <AlertTriangle className="w-4 h-4 text-destructive flex-shrink-0" />
                      )}
                    </div>
                  </td>
                  <td className="px-4 py-2">
                    <Input
                      type="number"
                      value={item.rate || ""}
                      placeholder="0.00"
                      onChange={(e) => updateItem(index, "rate", Number(e.target.value))}
                      className={`h-8 text-sm text-right font-mono ${item.isUncertain ? "border-destructive/50" : ""}`}
                      data-testid={`input-rate-${index}`}
                    />
                  </td>
                  <td className="px-4 py-2 text-right">
                    <span className="text-sm font-medium font-mono pr-2" data-testid={`text-amount-${index}`}>
                      {(item.amount ?? item.rate).toFixed(2)}
                    </span>
                  </td>
                  <td className="px-4 py-2 text-center">
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => removeItem(index)}
                      className="h-7 w-7 text-muted-foreground"
                      data-testid={`button-delete-${index}`}
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </Button>
                  </td>
                </tr>
              ))}
              {items.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-4 py-10 text-center text-sm text-muted-foreground">
                    No items extracted. Add items manually or try uploading again.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        <div className="border-t px-4 py-3 flex items-center justify-between gap-2">
          <Button variant="ghost" size="sm" onClick={addItem} data-testid="button-add-item">
            <Plus className="w-4 h-4 mr-1" />
            Add Item
          </Button>
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-3 text-sm text-muted-foreground">
              <span>SubTotal</span>
              <span className="font-mono font-medium text-foreground">{computedTotal.toFixed(2)}</span>
            </div>
            <div className="flex items-center gap-3">
              <span className="text-sm font-semibold">Total AED</span>
              <span className="text-xl font-bold font-mono" data-testid="text-total-amount">
                {total.toFixed(2)}
              </span>
            </div>
          </div>
        </div>
      </Card>
    </div>
  );
}

import { useCallback } from "react";
import { ArrowLeft, Download, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import type { Invoice, InvoiceItem } from "@shared/schema";

interface InvoicePreviewProps {
  invoice: Invoice & { items: InvoiceItem[] };
  onBack: () => void;
  onNewScan: () => void;
}

const COMPANY_NAME = "DigiBill";
const COMPANY_CITY = "ISLAMABAD, Pakistan";
const COMPANY_PHONE = "+923490896977";

export function InvoicePreview({ invoice, onBack, onNewScan }: InvoicePreviewProps) {
  const total = invoice.items.reduce((sum, item) => sum + (item.amount ?? item.rate), 0);

  const generatePDF = useCallback(async () => {
    const { jsPDF } = await import("jspdf");
    const autoTable = (await import("jspdf-autotable")).default;

    const doc = new jsPDF();
    const pageW = doc.internal.pageSize.getWidth();
    const pageH = doc.internal.pageSize.getHeight();
    const margin = 18;

    // ── HEADER BLOCK ───────────────────────────────────────────────
    // Left: logo mark + company name
    doc.setFillColor(29, 78, 216);          // blue square logo
    doc.roundedRect(margin, 14, 10, 10, 1.5, 1.5, "F");
    doc.setFillColor(255, 255, 255);
    doc.rect(margin + 2.5, 16.5, 5, 1.5, "F");
    doc.rect(margin + 2.5, 19.5, 5, 1.5, "F");
    doc.rect(margin + 2.5, 22, 3, 1.2, "F");

    doc.setTextColor(15, 23, 42);
    doc.setFontSize(14);
    doc.setFont("helvetica", "bold");
    doc.text(COMPANY_NAME, margin + 13, 21);

    doc.setFontSize(8.5);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(80, 90, 110);
    doc.text(COMPANY_CITY, margin + 13, 27);
    doc.text(COMPANY_PHONE, margin + 13, 32);

    // Right: INVOICE + number
    const invoiceNumStr = invoice.invoiceNumber.replace("INV-", "");
    doc.setFontSize(20);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(15, 23, 42);
    doc.text(`INVOICE ${invoiceNumStr}`, pageW - margin, 21, { align: "right" });

    // Separator line
    doc.setDrawColor(200, 210, 225);
    doc.setLineWidth(0.4);
    doc.line(margin, 38, pageW - margin, 38);

    // ── BILLING INFO ───────────────────────────────────────────────
    const col2X = pageW / 2 + 10;

    doc.setFontSize(7.5);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(100, 115, 135);
    doc.text("Billed To", margin, 46);
    doc.text("Invoice Number", col2X, 46);

    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(15, 23, 42);
    doc.text(invoice.clientName, margin, 53);
    doc.text(invoice.invoiceNumber, col2X, 53);

    doc.setFontSize(8.5);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(80, 90, 110);
    doc.text(invoice.clientAddress, margin, 59);

    // Date Issued
    doc.setFontSize(7.5);
    doc.setTextColor(100, 115, 135);
    doc.text("Date Issued", col2X, 60);
    doc.setFontSize(8.5);
    doc.setTextColor(80, 90, 110);
    const issuedDate = new Date(invoice.createdAt).toLocaleDateString("en-GB", {
      day: "numeric", month: "long", year: "numeric",
    });
    doc.text(issuedDate, col2X, 66);

    // Due Date
    doc.setFontSize(7.5);
    doc.setTextColor(100, 115, 135);
    doc.text("Due Date", col2X, 73);
    doc.setFontSize(8.5);
    doc.setTextColor(80, 90, 110);
    const dueDate = new Date(invoice.createdAt);
    dueDate.setDate(dueDate.getDate() + 30);
    doc.text(dueDate.toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" }), col2X, 79);

    // ── ITEMS TABLE ────────────────────────────────────────────────
    const tableData = invoice.items.map((item) => [
      item.description,
      item.rate.toFixed(2),
      (item.amount ?? item.rate).toFixed(2),
    ]);

    autoTable(doc, {
      startY: 88,
      head: [["Description", "Rate", "Amount"]],
      body: tableData,
      theme: "plain",
      headStyles: {
        fillColor: [248, 250, 252],
        textColor: [80, 90, 110],
        fontSize: 8,
        fontStyle: "bold",
        lineColor: [200, 210, 225],
        lineWidth: { bottom: 0.4, top: 0.4, left: 0, right: 0 },
        cellPadding: { top: 5, bottom: 5, left: 4, right: 4 },
      },
      bodyStyles: {
        fontSize: 8.5,
        textColor: [30, 40, 55],
        lineColor: [225, 232, 240],
        lineWidth: { bottom: 0.3, top: 0, left: 0, right: 0 },
        cellPadding: { top: 5, bottom: 5, left: 4, right: 4 },
      },
      columnStyles: {
        0: { cellWidth: "auto", halign: "left" },
        1: { cellWidth: 32, halign: "right" },
        2: { cellWidth: 36, halign: "right" },
      },
      margin: { left: margin, right: margin },
    });

    const finalY: number = (doc as any).lastAutoTable?.finalY ?? 160;

    // ── SUBTOTAL BLOCK ─────────────────────────────────────────────
    const blockX = pageW - margin - 80;
    const blockY = finalY + 8;

    doc.setDrawColor(200, 210, 225);
    doc.setLineWidth(0.3);
    doc.line(blockX, blockY, pageW - margin, blockY);

    doc.setFontSize(8.5);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(80, 90, 110);
    doc.text("SubTotal:", blockX, blockY + 8);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(15, 23, 42);
    doc.text(`${total.toFixed(2)}`, pageW - margin, blockY + 8, { align: "right" });

    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(100, 115, 135);
    doc.text("AED", pageW - margin, blockY + 14, { align: "right" });

    doc.setDrawColor(200, 210, 225);
    doc.line(blockX, blockY + 18, pageW - margin, blockY + 18);

    // ── FOOTER ─────────────────────────────────────────────────────
    doc.setFontSize(7);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(160, 170, 185);
    doc.text(`Made with ${COMPANY_NAME} · Digital Invoice Solutions`, pageW / 2, pageH - 10, { align: "center" });

    doc.save(`${invoice.invoiceNumber}.pdf`);
  }, [invoice, total]);

  // ── ON-SCREEN PREVIEW ──────────────────────────────────────────
  const invoiceDate = new Date(invoice.createdAt).toLocaleDateString("en-GB", {
    day: "numeric", month: "long", year: "numeric",
  });
  const dueDate = new Date(invoice.createdAt);
  dueDate.setDate(dueDate.getDate() + 30);

  return (
    <div className="space-y-4">
      {/* Toolbar */}
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="icon" onClick={onBack} data-testid="button-back-to-editor">
            <ArrowLeft className="w-4 h-4" />
          </Button>
          <div>
            <h2 className="text-xl font-semibold" data-testid="text-preview-title">Invoice Preview</h2>
            <p className="text-sm text-muted-foreground">
              <span className="font-mono font-medium">{invoice.invoiceNumber}</span>
              {" "}&middot; {invoice.clientName}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="secondary" onClick={onNewScan} data-testid="button-new-scan-preview">
            <Plus className="w-4 h-4 mr-2" />
            New Scan
          </Button>
          <Button onClick={generatePDF} data-testid="button-generate-pdf">
            <Download className="w-4 h-4 mr-2" />
            Download PDF
          </Button>
        </div>
      </div>

      {/* Paper-style invoice card */}
      <Card className="p-8 max-w-2xl mx-auto shadow-md bg-white dark:bg-card">
        {/* Header */}
        <div className="flex items-start justify-between mb-6">
          {/* Left: company */}
          <div>
            <div className="flex items-center gap-2 mb-1">
              <div className="w-7 h-7 rounded bg-primary flex items-center justify-center flex-shrink-0">
                <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
                  <rect x="2" y="3" width="10" height="1.8" rx="0.5" fill="white"/>
                  <rect x="2" y="6.2" width="10" height="1.8" rx="0.5" fill="white"/>
                  <rect x="2" y="9.2" width="6" height="1.5" rx="0.5" fill="white"/>
                </svg>
              </div>
              <span className="text-base font-bold text-foreground">{COMPANY_NAME}</span>
            </div>
            <p className="text-xs text-muted-foreground">{COMPANY_CITY}</p>
            <p className="text-xs text-muted-foreground">{COMPANY_PHONE}</p>
          </div>
          {/* Right: invoice title */}
          <div className="text-right">
            <p className="text-2xl font-bold text-foreground tracking-tight">
              INVOICE {invoice.invoiceNumber.replace("INV-", "")}
            </p>
          </div>
        </div>

        <hr className="border-border mb-5" />

        {/* Billing + invoice meta */}
        <div className="grid grid-cols-2 gap-6 mb-6">
          <div>
            <p className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground mb-1.5">Billed To</p>
            <p className="text-sm font-bold text-foreground">{invoice.clientName}</p>
            <p className="text-xs text-muted-foreground leading-relaxed">{invoice.clientAddress}</p>
          </div>
          <div className="space-y-2">
            <div>
              <p className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">Invoice Number</p>
              <p className="text-sm font-semibold text-foreground font-mono">{invoice.invoiceNumber}</p>
            </div>
            <div>
              <p className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">Date Issued</p>
              <p className="text-xs text-muted-foreground">{invoiceDate}</p>
            </div>
            <div>
              <p className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">Due Date</p>
              <p className="text-xs text-muted-foreground">
                {dueDate.toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" })}
              </p>
            </div>
          </div>
        </div>

        {/* Items table */}
        <div className="border border-border rounded-sm overflow-hidden mb-5">
          <table className="w-full" data-testid="table-preview-items">
            <thead>
              <tr className="bg-muted/40 border-b border-border">
                <th className="text-left text-[10px] font-semibold uppercase tracking-wider text-muted-foreground px-4 py-2.5">
                  Description
                </th>
                <th className="text-right text-[10px] font-semibold uppercase tracking-wider text-muted-foreground px-4 py-2.5 w-24">
                  Rate
                </th>
                <th className="text-right text-[10px] font-semibold uppercase tracking-wider text-muted-foreground px-4 py-2.5 w-28">
                  Amount
                </th>
              </tr>
            </thead>
            <tbody>
              {invoice.items.map((item, i) => (
                <tr
                  key={item.id}
                  className="border-b border-border/60 last:border-b-0"
                  data-testid={`row-preview-${i}`}
                >
                  <td className="px-4 py-2.5 text-sm font-mono font-medium text-foreground">
                    {item.description}
                  </td>
                  <td className="px-4 py-2.5 text-sm text-right font-mono text-muted-foreground">
                    {item.rate.toFixed(2)}
                  </td>
                  <td className="px-4 py-2.5 text-sm text-right font-mono font-semibold text-foreground">
                    {(item.amount ?? item.rate).toFixed(2)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Subtotal block */}
        <div className="flex justify-end">
          <div className="min-w-[200px] border-t border-border pt-3 space-y-1">
            <div className="flex items-center justify-between gap-8">
              <span className="text-sm text-muted-foreground">SubTotal:</span>
              <span className="text-sm font-semibold font-mono" data-testid="text-preview-total">
                {total.toFixed(2)}
              </span>
            </div>
            <div className="flex justify-end">
              <span className="text-xs text-muted-foreground">AED</span>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="mt-8 pt-4 border-t border-border/50">
          <p className="text-[10px] text-center text-muted-foreground/60">
            Made with {COMPANY_NAME} &middot; Digital Invoice Solutions
          </p>
        </div>
      </Card>
    </div>
  );
