@tailwind base;
@tailwind components;
@tailwind utilities;

/* ─── LIGHT MODE (Corporate Precision) ─────────────────────── */
:root {
  --button-outline: rgba(0,0,0, .12);
  --badge-outline: rgba(0,0,0, .06);
  --opaque-button-border-intensity: -8;
  --elevate-1: rgba(0,0,0, .03);
  --elevate-2: rgba(0,0,0, .07);

  /* Surfaces */
  --background:    220 8% 97%;
  --foreground:    220 8% 10%;
  --border:        220 6% 84%;
  --card:          0 0% 100%;
  --card-foreground: 220 8% 10%;
  --card-border:   220 6% 90%;
  --popover:       0 0% 100%;
  --popover-foreground: 220 8% 10%;
  --popover-border: 220 6% 84%;

  /* Primary: near-black charcoal */
  --primary:           220 8% 8%;
  --primary-foreground: 0 0% 100%;
  --primary-border:    hsl(220 8% 8%);

  /* Secondary: amber/gold */
  --secondary:           38 100% 26%;
  --secondary-foreground: 0 0% 100%;
  --secondary-border:    hsl(38 100% 26%);

  /* Muted */
  --muted:           220 6% 92%;
  --muted-foreground: 220 6% 42%;

  /* Accent */
  --accent:           38 80% 95%;
  --accent-foreground: 38 100% 22%;
  --accent-border:    hsl(38 60% 88%);

  /* Destructive */
  --destructive:           0 75% 40%;
  --destructive-foreground: 0 0% 100%;
  --destructive-border:    hsl(0 75% 40%);

  /* Inputs / Ring */
  --input: 220 6% 78%;
  --ring:  220 8% 15%;

  /* Sidebar */
  --sidebar:                   220 6% 95%;
  --sidebar-foreground:        220 8% 10%;
  --sidebar-border:            220 6% 88%;
  --sidebar-primary:           220 8% 8%;
  --sidebar-primary-foreground: 0 0% 100%;
  --sidebar-primary-border:    hsl(220 8% 8%);
  --sidebar-accent:            220 6% 90%;
  --sidebar-accent-foreground: 220 8% 15%;
  --sidebar-accent-border:     hsl(220 6% 84%);
  --sidebar-ring:              220 8% 15%;

  /* Fonts */
  --font-sans:  'Hanken Grotesk', 'Inter', sans-serif;
  --font-label: 'Inter', sans-serif;
  --font-mono:  'Courier Prime', 'JetBrains Mono', monospace;

  /* Shape */
  --radius: 0.375rem;

  /* Charts */
  --chart-1: 220 8% 12%;
  --chart-2: 38 100% 40%;
  --chart-3: 197 58% 42%;
  --chart-4: 43 74% 49%;
  --chart-5: 27 87% 42%;

  /* Shadows (subtle — tonal depth, not heavy drop shadows) */
  --shadow-2xs: 0 1px 2px hsl(220 8% 10% / 0.04);
  --shadow-xs:  0 1px 3px hsl(220 8% 10% / 0.06);
  --shadow-sm:  0 2px 6px hsl(220 8% 10% / 0.07), 0 1px 2px hsl(220 8% 10% / 0.04);
  --shadow:     0 2px 8px hsl(220 8% 10% / 0.08), 0 1px 3px hsl(220 8% 10% / 0.05);
  --shadow-md:  0 4px 16px hsl(220 8% 10% / 0.09), 0 2px 6px hsl(220 8% 10% / 0.05);
  --shadow-lg:  0 8px 24px hsl(220 8% 10% / 0.10), 0 4px 8px hsl(220 8% 10% / 0.06);
  --shadow-xl:  0 16px 40px hsl(220 8% 10% / 0.12), 0 8px 16px hsl(220 8% 10% / 0.07);
  --shadow-2xl: 0 24px 64px hsl(220 8% 10% / 0.15);
}

/* ─── DARK MODE ─────────────────────────────────────────────── */
.dark {
  --button-outline: rgba(255,255,255, .12);
  --badge-outline: rgba(255,255,255, .06);
  --opaque-button-border-intensity: 9;
  --elevate-1: rgba(255,255,255, .04);
  --elevate-2: rgba(255,255,255, .09);

  --background:    220 8% 9%;
  --foreground:    220 5% 93%;
  --border:        220 6% 20%;
  --card:          220 8% 11%;
  --card-foreground: 220 5% 93%;
  --card-border:   220 6% 16%;
  --popover:       220 8% 13%;
  --popover-foreground: 220 5% 93%;
  --popover-border: 220 6% 18%;

  --primary:           38 90% 55%;
  --primary-foreground: 220 8% 8%;
  --primary-border:    hsl(38 90% 55%);

  --secondary:           220 6% 22%;
  --secondary-foreground: 220 5% 90%;
  --secondary-border:    hsl(220 6% 22%);

  --muted:           220 6% 18%;
  --muted-foreground: 220 5% 60%;

  --accent:           38 60% 18%;
  --accent-foreground: 38 90% 75%;
  --accent-border:    hsl(38 40% 25%);

  --destructive:           0 70% 45%;
  --destructive-foreground: 0 0% 98%;
  --destructive-border:    hsl(0 70% 45%);

  --input: 220 6% 30%;
  --ring:  38 90% 55%;

  --sidebar:                   220 8% 11%;
  --sidebar-foreground:        220 5% 90%;
  --sidebar-border:            220 6% 18%;
  --sidebar-primary:           38 90% 55%;
  --sidebar-primary-foreground: 220 8% 8%;
  --sidebar-primary-border:    hsl(38 90% 55%);
  --sidebar-accent:            220 6% 18%;
  --sidebar-accent-foreground: 220 5% 85%;
  --sidebar-accent-border:     hsl(220 6% 22%);
  --sidebar-ring:              38 90% 55%;

  --chart-1: 38 90% 60%;
  --chart-2: 197 58% 60%;
  --chart-3: 220 8% 60%;
  --chart-4: 43 74% 60%;
  --chart-5: 27 87% 55%;

  --shadow-2xs: 0 1px 2px hsl(0 0% 0% / 0.20);
  --shadow-xs:  0 1px 3px hsl(0 0% 0% / 0.25);
  --shadow-sm:  0 2px 6px hsl(0 0% 0% / 0.28), 0 1px 2px hsl(0 0% 0% / 0.20);
  --shadow:     0 2px 8px hsl(0 0% 0% / 0.30), 0 1px 3px hsl(0 0% 0% / 0.22);
  --shadow-md:  0 4px 16px hsl(0 0% 0% / 0.32), 0 2px 6px hsl(0 0% 0% / 0.24);
  --shadow-lg:  0 8px 24px hsl(0 0% 0% / 0.36), 0 4px 8px hsl(0 0% 0% / 0.26);
  --shadow-xl:  0 16px 40px hsl(0 0% 0% / 0.40), 0 8px 16px hsl(0 0% 0% / 0.28);
  --shadow-2xl: 0 24px 64px hsl(0 0% 0% / 0.48);
}

/* ─── BASE ──────────────────────────────────────────────────── */
@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply font-sans antialiased bg-background text-foreground;
    font-feature-settings: "cv02", "cv03", "cv04", "cv11";
  }
  h1, h2, h3, h4 {
    font-family: var(--font-sans);
    letter-spacing: -0.01em;
  }
}

/* ─── ANIMATIONS ────────────────────────────────────────────── */
@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@keyframes slide-up {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes slide-down {
  from { opacity: 0; transform: translateY(-12px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes slide-in-right {
  from { opacity: 0; transform: translateX(24px); }
  to   { opacity: 1; transform: translateX(0); }
}

@keyframes slide-in-left {
  from { opacity: 0; transform: translateX(-24px); }
  to   { opacity: 1; transform: translateX(0); }
}

@keyframes scale-in {
  from { opacity: 0; transform: scale(0.96); }
  to   { opacity: 1; transform: scale(1); }
}

@keyframes shimmer {
  0%   { background-position: -400px 0; }
  100% { background-position: 400px 0; }
}

@keyframes pulse-ring {
  0%   { transform: scale(0.95); opacity: 0.8; }
  50%  { transform: scale(1.05); opacity: 0.4; }
  100% { transform: scale(0.95); opacity: 0.8; }
}

@keyframes spin-slow {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

.animate-fade-in      { animation: fade-in 0.35s ease both; }
.animate-slide-up     { animation: slide-up 0.4s cubic-bezier(0.16, 1, 0.3, 1) both; }
.animate-slide-down   { animation: slide-down 0.3s cubic-bezier(0.16, 1, 0.3, 1) both; }
.animate-slide-in-right { animation: slide-in-right 0.4s cubic-bezier(0.16, 1, 0.3, 1) both; }
.animate-slide-in-left  { animation: slide-in-left 0.4s cubic-bezier(0.16, 1, 0.3, 1) both; }
.animate-scale-in     { animation: scale-in 0.35s cubic-bezier(0.16, 1, 0.3, 1) both; }

/* Stagger helpers */
.delay-50   { animation-delay: 50ms; }
.delay-100  { animation-delay: 100ms; }
.delay-150  { animation-delay: 150ms; }
.delay-200  { animation-delay: 200ms; }
.delay-300  { animation-delay: 300ms; }

/* Shimmer loading */
.shimmer {
  background: linear-gradient(
    90deg,
    hsl(var(--muted)) 25%,
    hsl(var(--border)) 50%,
    hsl(var(--muted)) 75%
  );
  background-size: 800px 100%;
  animation: shimmer 1.6s infinite linear;
}

/* ─── ELEVATION SYSTEM ──────────────────────────────────────── */
@layer utilities {
  input[type="search"]::-webkit-search-cancel-button { @apply hidden; }

  [contenteditable][data-placeholder]:empty::before {
    content: attr(data-placeholder);
    color: hsl(var(--muted-foreground));
    pointer-events: none;
  }

  .no-default-hover-elevate {}
  .no-default-active-elevate {}

  .toggle-elevate::before,
  .toggle-elevate-2::before {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    border-radius: inherit;
    z-index: -1;
  }

  .toggle-elevate.toggle-elevated::before {
    background-color: var(--elevate-2);
  }

  .border.toggle-elevate::before { inset: -1px; }

  .hover-elevate:not(.no-default-hover-elevate),
  .active-elevate:not(.no-default-active-elevate),
  .hover-elevate-2:not(.no-default-hover-elevate),
  .active-elevate-2:not(.no-default-active-elevate) {
    position: relative;
    z-index: 0;
  }

  .hover-elevate:not(.no-default-hover-elevate)::after,
  .active-elevate:not(.no-default-active-elevate)::after,
  .hover-elevate-2:not(.no-default-hover-elevate)::after,
  .active-elevate-2:not(.no-default-active-elevate)::after {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    border-radius: inherit;
    z-index: 999;
  }

  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
  .active-elevate:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-1);
  }

  .hover-elevate-2:hover:not(.no-default-hover-elevate)::after,
  .active-elevate-2:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-2);
  }

  .border.hover-elevate:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate-2:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate-2:not(.no-active-interaction-elevate)::after {
    inset: -1px;
  }
}

