import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { ImageUploader } from "@/components/image-uploader";
import { InvoiceEditor } from "@/components/invoice-editor";
import { InvoiceHistory } from "@/components/invoice-history";
import { InvoicePreview } from "@/components/invoice-preview";
import { ThemeToggle } from "@/components/theme-toggle";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import type { ExtractedItem, Invoice, InvoiceItem } from "@shared/schema";
import { History, ScanLine } from "lucide-react";
import { Button } from "@/components/ui/button";

type AppView = "upload" | "editor" | "preview" | "history";

export default function Home() {
  const [view, setView] = useState<AppView>("upload");
  const [extractedItems, setExtractedItems] = useState<ExtractedItem[]>([]);
  const [extractedGrandTotal, setExtractedGrandTotal] = useState<number>(0);
  const [currentInvoice, setCurrentInvoice] = useState<(Invoice & { items: InvoiceItem[] }) | null>(null);
  const [invoiceNumber, setInvoiceNumber] = useState("INV-39");
  const { toast } = useToast();

  const invoiceNumberQuery = useQuery<{ invoiceNumber: string }>({
    queryKey: ["/api/invoice-number"],
  });

  const currentInvNum = invoiceNumberQuery.data?.invoiceNumber || invoiceNumber;

  const extractMutation = useMutation({
    mutationFn: async (formData: FormData) => {
      const res = await fetch("/api/extract", { method: "POST", body: formData });
      if (!res.ok) throw new Error("Failed to extract data");
      return res.json();
    },
    onSuccess: (data) => {
      setExtractedItems(data.items || []);
      setExtractedGrandTotal(data.grandTotal || 0);
      setView("editor");
      toast({
        title: "Extraction complete",
        description: `Found ${data.items?.length || 0} items in the image.`,
      });
    },
    onError: () => {
      toast({
        title: "Extraction failed",
        description: "Could not extract data from the image. Please try again.",
        variant: "destructive",
      });
    },
  });

  const saveMutation = useMutation({
    mutationFn: async (data: { items: ExtractedItem[]; totalAmount: number }) => {
      const res = await apiRequest("POST", "/api/invoices", {
        invoiceNumber: currentInvNum,
        clientName: "ART FASHION LLC",
        clientAddress: "Abu Dhabi, UAE",
        currency: "AED",
        totalAmount: data.totalAmount,
        items: data.items,
      });
      return res.json();
    },
    onSuccess: (data) => {
      setCurrentInvoice(data);
      setView("preview");
      queryClient.invalidateQueries({ queryKey: ["/api/invoices"] });
      queryClient.invalidateQueries({ queryKey: ["/api/invoice-number"] });
      toast({ title: "Invoice saved", description: `${data.invoiceNumber} created.` });
    },
    onError: () => {
      toast({ title: "Save failed", description: "Could not save the invoice.", variant: "destructive" });
    },
  });

  const handleImageUpload = (formData: FormData) => extractMutation.mutate(formData);

  const handleSaveInvoice = (items: ExtractedItem[], grandTotal: number) => {
    saveMutation.mutate({ items, totalAmount: grandTotal });
  };

  const handleViewInvoice = async (invoice: Invoice) => {
    try {
      const res = await fetch(`/api/invoices/${invoice.id}`);
      if (!res.ok) throw new Error("Failed");
      const data = await res.json();
      setCurrentInvoice(data);
      setView("preview");
    } catch {
      toast({ title: "Error", description: "Could not load invoice.", variant: "destructive" });
    }
  };

  const goToUpload = () => { setView("upload"); setExtractedItems([]); setCurrentInvoice(null); };

  return (
    <div className="min-h-screen bg-background">
      {/* ── Header ── */}
      <header className="sticky top-0 z-50 border-b border-border bg-card/90 backdrop-blur-md animate-slide-down">
        <div className="mx-auto max-w-5xl flex items-center justify-between gap-2 px-5 py-0 h-14">
          {/* Logo */}
          <div className="flex items-center gap-3">
            <div className="flex items-center justify-center w-8 h-8 rounded-md bg-primary">
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                <rect x="2" y="3.5" width="12" height="2" rx="0.75" fill="white"/>
                <rect x="2" y="7" width="12" height="2" rx="0.75" fill="white"/>
                <rect x="2" y="10.5" width="7.5" height="1.8" rx="0.75" fill="white"/>
              </svg>
            </div>
            <div>
              <h1
                className="text-[15px] font-bold leading-tight tracking-tight text-foreground"
                data-testid="text-app-title"
              >
                DigiBill
              </h1>
              <p className="text-[10px] font-label uppercase tracking-widest text-muted-foreground leading-tight">
                Digital Invoice Solutions
              </p>
            </div>
          </div>

          {/* Nav */}
          <nav className="flex items-center gap-1">
            <Button
              variant={view === "upload" || view === "editor" || view === "preview" ? "ghost" : "ghost"}
              size="sm"
              onClick={goToUpload}
              className={`text-xs font-label uppercase tracking-wider transition-all ${
                view !== "history"
                  ? "text-primary border-b-2 border-primary rounded-none pb-[2px]"
                  : "text-muted-foreground hover:text-foreground"
              }`}
              data-testid="button-new-scan"
            >
              <ScanLine className="w-3.5 h-3.5 mr-1.5" />
              New Scan
            </Button>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setView("history")}
              className={`text-xs font-label uppercase tracking-wider transition-all ${
                view === "history"
                  ? "text-primary border-b-2 border-primary rounded-none pb-[2px]"
                  : "text-muted-foreground hover:text-foreground"
              }`}
              data-testid="button-history"
            >
              <History className="w-3.5 h-3.5 mr-1.5" />
              History
            </Button>
            <div className="ml-2 pl-2 border-l border-border">
              <ThemeToggle />
            </div>
          </nav>
        </div>
      </header>

      {/* ── Main ── */}
      <main className="mx-auto max-w-5xl px-5 py-8">
        {view === "upload" && (
          <div className="animate-slide-up">
            <ImageUploader onUpload={handleImageUpload} isLoading={extractMutation.isPending} />
          </div>
        )}

        {view === "editor" && (
          <div className="animate-slide-in-right">
            <InvoiceEditor
              items={extractedItems}
              invoiceNumber={currentInvNum}
              grandTotal={extractedGrandTotal}
              onSave={handleSaveInvoice}
              onBack={() => setView("upload")}
              isSaving={saveMutation.isPending}
            />
          </div>
        )}

        {view === "preview" && currentInvoice && (
          <div className="animate-slide-in-right">
            <InvoicePreview
              invoice={currentInvoice}
              onBack={() => setView("editor")}
              onNewScan={goToUpload}
            />
          </div>
        )}

        {view === "history" && (
          <div className="animate-slide-up">
            <InvoiceHistory onViewInvoice={handleViewInvoice} />
          </div>
        )}
      </main>
    </div>
  );
}

import { useState, useRef, useCallback } from "react";
import { Upload, Camera, Image, Loader2, FileImage, Scan } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";

interface ImageUploaderProps {
  onUpload: (formData: FormData) => void;
  isLoading: boolean;
}

export function ImageUploader({ onUpload, isLoading }: ImageUploaderProps) {
  const [preview, setPreview] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  const handleFile = useCallback((file: File) => {
    if (!file.type.startsWith("image/")) return;
    const reader = new FileReader();
    reader.onload = (e) => setPreview(e.target?.result as string);
    reader.readAsDataURL(file);
    const formData = new FormData();
    formData.append("image", file);
    onUpload(formData);
  }, [onUpload]);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files[0];
    if (file) handleFile(file);
  }, [handleFile]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) handleFile(file);
  };

  return (
    <div className="flex flex-col items-center gap-8 max-w-2xl mx-auto">
      {/* Hero heading */}
      <div className="text-center space-y-3 animate-slide-up">
        <div className="inline-flex items-center justify-center w-14 h-14 rounded-xl bg-primary/8 mb-1 transition-transform hover:scale-105">
          <FileImage className="w-7 h-7 text-primary" />
        </div>
        <h2
          className="text-2xl font-bold tracking-tight text-foreground"
          data-testid="text-upload-title"
        >
          Upload Invoice Note
        </h2>
        <p className="text-sm text-muted-foreground leading-relaxed max-w-md">
          Photo or scan of any handwritten note. The AI reads model numbers and rates
          automatically — the last number is treated as the grand total.
        </p>
      </div>

      {/* Drop zone */}
      <div className="w-full animate-slide-up delay-100">
        <div
          className={`
            group relative w-full rounded-xl border-2 border-dashed
            transition-all duration-300 cursor-pointer min-h-[260px]
            flex flex-col items-center justify-center gap-4 p-10
            ${dragOver
              ? "border-primary bg-primary/5 scale-[1.01]"
              : "border-border hover:border-primary/50 hover:bg-muted/30 bg-card"
            }
          `}
          onDrop={handleDrop}
          onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
          onDragLeave={() => setDragOver(false)}
          onClick={() => !isLoading && fileInputRef.current?.click()}
          data-testid="dropzone-upload"
        >
          {isLoading ? (
            <div className="flex flex-col items-center gap-5">
              <div className="relative w-16 h-16">
                <div className="absolute inset-0 rounded-full border-4 border-primary/20 animate-ping" />
                <div className="absolute inset-0 rounded-full border-4 border-primary/10" />
                <div className="absolute inset-2 rounded-full bg-primary/5 flex items-center justify-center">
                  <Loader2 className="w-7 h-7 text-primary animate-spin" />
                </div>
              </div>
              <div className="text-center">
                <p className="font-semibold text-foreground" data-testid="text-processing">
                  Analyzing note…
                </p>
                <p className="text-sm text-muted-foreground mt-1">
                  AI is extracting invoice data
                </p>
              </div>
              {/* Progress shimmer */}
              <div className="w-48 h-1 rounded-full overflow-hidden bg-muted">
                <div className="h-full bg-primary/60 rounded-full animate-[shimmer_1.4s_ease-in-out_infinite]" style={{width:"60%"}} />
              </div>
            </div>
          ) : preview ? (
            <div className="flex flex-col items-center gap-3 animate-scale-in">
              <img
                src={preview}
                alt="Preview"
                className="max-h-44 rounded-lg object-contain shadow-md"
                data-testid="img-preview"
              />
              <p className="text-xs text-muted-foreground">Click or drop another image to replace</p>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-3 animate-fade-in">
              <div className="w-14 h-14 rounded-xl bg-muted flex items-center justify-center transition-transform group-hover:scale-105 group-hover:bg-primary/10">
                <Upload className="w-6 h-6 text-muted-foreground group-hover:text-primary transition-colors" />
              </div>
              <div className="text-center">
                <p className="font-semibold text-foreground">
                  Drop your handwritten note here
                </p>
                <p className="text-sm text-muted-foreground mt-1">or click to browse files</p>
              </div>
              <div className="flex items-center gap-1.5 mt-1 text-xs text-muted-foreground/70">
                <Image className="w-3 h-3" />
                <span>JPG · PNG · WEBP · up to 10 MB</span>
              </div>
            </div>
          )}

          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            className="hidden"
            onChange={handleFileChange}
            data-testid="input-file-upload"
          />
        </div>
      </div>

      {/* Camera button */}
      <div className="flex items-center gap-3 animate-slide-up delay-150">
        <Button
          variant="outline"
          onClick={() => cameraInputRef.current?.click()}
          disabled={isLoading}
          className="gap-2 transition-all hover:shadow-sm"
          data-testid="button-camera"
        >
          <Camera className="w-4 h-4" />
          Take Photo
        </Button>
        <input
          ref={cameraInputRef}
          type="file"
          accept="image/*"
          capture="environment"
          className="hidden"
          onChange={handleFileChange}
        />
      </div>

      {/* How it works */}
      <Card className="w-full p-6 animate-slide-up delay-200">
        <p className="text-xs font-label uppercase tracking-widest text-muted-foreground mb-5">
          How it works
        </p>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
          {[
            { step: "01", title: "Upload", desc: "Photo of any handwritten invoice note" },
            { step: "02", title: "Extract", desc: "AI reads model numbers, rates & grand total" },
            { step: "03", title: "Export", desc: "Download a clean, professional PDF invoice" },
          ].map((item, i) => (
            <div key={item.step} className="flex items-start gap-4">
              <div className="flex-shrink-0 w-8 h-8 rounded-lg bg-primary text-primary-foreground flex items-center justify-center">
                <span className="text-[10px] font-bold font-label tracking-wider">{item.step}</span>
              </div>
              <div>
                <p className="text-sm font-semibold text-foreground">{item.title}</p>
                <p className="text-xs text-muted-foreground mt-0.5 leading-relaxed">{item.desc}</p>
              </div>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import { Trash2, Plus, ArrowLeft, Save, AlertTriangle, Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import type { ExtractedItem } from "@shared/schema";

interface InvoiceEditorProps {
  items: ExtractedItem[];
  invoiceNumber: string;
  grandTotal?: number;
  onSave: (items: ExtractedItem[], grandTotal: number) => void;
  onBack: () => void;
  isSaving: boolean;
}

export function InvoiceEditor({
  items: initialItems,
  invoiceNumber,
  grandTotal: initialGrandTotal,
  onSave,
  onBack,
  isSaving,
}: InvoiceEditorProps) {
  const [items, setItems] = useState<ExtractedItem[]>(initialItems);

  useEffect(() => { setItems(initialItems); }, [initialItems]);

  const computedTotal = items.reduce((sum, item) => sum + (item.amount ?? item.rate), 0);
  const displayTotal = (initialGrandTotal && initialGrandTotal > 0) ? initialGrandTotal : computedTotal;

  const updateItem = useCallback((index: number, field: keyof ExtractedItem, value: string | number | boolean) => {
    setItems(prev => {
      const updated = [...prev];
      updated[index] = { ...updated[index], [field]: value };
      if (field === "rate") {
        updated[index].amount = Number(value);
        updated[index].quantity = 1;
      }
      if (field === "description" || field === "rate") {
        updated[index].isUncertain = false;
      }
      return updated;
    });
  }, []);

  const removeItem = useCallback((index: number) => {
    setItems(prev => prev.filter((_, i) => i !== index));
  }, []);

  const addItem = useCallback(() => {
    setItems(prev => [...prev, { description: "", quantity: 1, rate: 0, amount: 0, isUncertain: false }]);
  }, []);

  const uncertainCount = items.filter(i => i.isUncertain).length;
  const saveTotal = items.reduce((sum, item) => sum + (item.amount ?? item.rate), 0);

  return (
    <div className="max-w-4xl mx-auto space-y-5">
      {/* Toolbar */}
      <div className="flex items-center justify-between gap-3 flex-wrap animate-slide-down">
        <div className="flex items-center gap-3">
          <Button
            variant="ghost"
            size="icon"
            onClick={onBack}
            className="rounded-lg hover:bg-muted transition-colors"
            data-testid="button-back-to-upload"
          >
            <ArrowLeft className="w-4 h-4" />
          </Button>
          <div>
            <h2 className="text-lg font-bold tracking-tight text-foreground" data-testid="text-editor-title">
              Edit Extracted Items
            </h2>
            <p className="text-xs font-label uppercase tracking-wider text-muted-foreground">
              {invoiceNumber} &middot; ART FASHION LLC
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {uncertainCount > 0 && (
            <Badge
              variant="destructive"
              className="gap-1.5 animate-fade-in"
              data-testid="badge-uncertain-count"
            >
              <AlertTriangle className="w-3 h-3" />
              {uncertainCount} uncertain
            </Badge>
          )}
          <Button
            onClick={() => onSave(items, saveTotal)}
            disabled={isSaving || items.length === 0}
            className="gap-2 transition-all hover:shadow-sm"
            data-testid="button-save-invoice"
          >
            {isSaving ? (
              <>
                <div className="w-4 h-4 rounded-full border-2 border-primary-foreground/30 border-t-primary-foreground animate-spin" />
                Saving…
              </>
            ) : (
              <>
                <Save className="w-4 h-4" />
                Save &amp; Preview
              </>
            )}
          </Button>
        </div>
      </div>

      {/* Table card */}
      <Card className="overflow-hidden animate-slide-up border-border shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full" data-testid="table-invoice-items">
            <thead>
              <tr className="bg-muted/50 border-b-2 border-border">
                <th className="text-left text-[10px] font-label uppercase tracking-widest text-muted-foreground px-5 py-3 w-8">
                  #
                </th>
                <th className="text-left text-[10px] font-label uppercase tracking-widest text-muted-foreground px-5 py-3">
                  Description
                </th>
                <th className="text-right text-[10px] font-label uppercase tracking-widest text-muted-foreground px-5 py-3 w-36">
                  Rate (AED)
                </th>
                <th className="text-right text-[10px] font-label uppercase tracking-widest text-muted-foreground px-5 py-3 w-36">
                  Amount (AED)
                </th>
                <th className="w-10 px-3 py-3" />
              </tr>
            </thead>
            <tbody>
              {items.map((item, index) => (
                <tr
                  key={index}
                  className={`
                    border-b border-border/60 last:border-b-0
                    transition-colors duration-150
                    ${item.isUncertain ? "bg-destructive/4 hover:bg-destructive/6" : "hover:bg-muted/30"}
                  `}
                  style={{ animationDelay: `${index * 30}ms` }}
                  data-testid={`row-item-${index}`}
                >
                  <td className="px-5 py-3 text-sm text-muted-foreground tabular-nums">
                    {index + 1}
                  </td>
                  <td className="px-5 py-3">
                    <div className="flex items-center gap-2">
                      <Input
                        value={item.description.includes("[???]") ? "" : item.description}
                        placeholder={item.isUncertain ? "[???] — verify this item" : "Item description"}
                        onChange={(e) => updateItem(index, "description", e.target.value)}
                        className={`h-8 text-sm font-mono border-transparent bg-transparent focus:bg-card focus:border-border transition-all ${
                          item.isUncertain
                            ? "placeholder:text-destructive/60 text-destructive"
                            : ""
                        }`}
                        data-testid={`input-description-${index}`}
                      />
                      {item.isUncertain && (
                        <AlertTriangle className="w-3.5 h-3.5 text-destructive flex-shrink-0" />
                      )}
                    </div>
                  </td>
                  <td className="px-5 py-3">
                    <Input
                      type="number"
                      value={item.rate || ""}
                      placeholder="0.00"
                      onChange={(e) => updateItem(index, "rate", Number(e.target.value))}
                      className="h-8 text-sm text-right font-mono border-transparent bg-transparent focus:bg-card focus:border-border transition-all"
                      data-testid={`input-rate-${index}`}
                    />
                  </td>
                  <td className="px-5 py-3 text-right">
                    <span
                      className="text-sm font-mono font-medium text-foreground tabular-nums"
                      data-testid={`text-amount-${index}`}
                    >
                      {(item.amount ?? item.rate).toFixed(2)}
                    </span>
                  </td>
                  <td className="px-3 py-3 text-center">
                    <button
                      onClick={() => removeItem(index)}
                      className="w-7 h-7 rounded-md flex items-center justify-center text-muted-foreground/50 hover:text-destructive hover:bg-destructive/8 transition-all"
                      data-testid={`button-delete-${index}`}
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </td>
                </tr>
              ))}

              {items.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-5 py-14 text-center text-sm text-muted-foreground">
                    No items yet. Add items manually or go back and upload an image.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Footer row */}
        <div className="border-t border-border bg-muted/20 px-5 py-3 flex items-center justify-between gap-2">
          <Button
            variant="ghost"
            size="sm"
            onClick={addItem}
            className="gap-1.5 text-muted-foreground hover:text-foreground transition-colors"
            data-testid="button-add-item"
          >
            <Plus className="w-3.5 h-3.5" />
            Add item
          </Button>

          <div className="flex items-center gap-6">
            <div className="flex items-center gap-3 text-sm">
              <span className="text-muted-foreground">SubTotal</span>
              <span className="font-mono tabular-nums text-foreground">{computedTotal.toFixed(2)}</span>
            </div>
            <div className="h-5 w-px bg-border" />
            <div className="flex items-center gap-3">
              <span className="text-[10px] font-label uppercase tracking-widest text-muted-foreground">
                Total AED
              </span>
              <span
                className="text-xl font-bold font-mono tabular-nums text-foreground"
                data-testid="text-total-amount"
              >
                {displayTotal.toFixed(2)}
              </span>
            </div>
          </div>
        </div>
      </Card>
    </div>
  );
}

import { useCallback } from "react";
import { ArrowLeft, Download, Plus, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import type { Invoice, InvoiceItem } from "@shared/schema";

interface InvoicePreviewProps {
  invoice: Invoice & { items: InvoiceItem[] };
  onBack: () => void;
  onNewScan: () => void;
}

const CO_NAME  = "DigiBill";
const CO_CITY  = "ISLAMABAD, Pakistan";
const CO_PHONE = "+923490896977";
const CO_EMAIL = "info@digibill.io";

export function InvoicePreview({ invoice, onBack, onNewScan }: InvoicePreviewProps) {
  const total = invoice.items.reduce((sum, item) => sum + (item.amount ?? item.rate), 0);

  /* ── PDF generation – matches INV-43 layout ── */
  const generatePDF = useCallback(async () => {
    const { jsPDF } = await import("jspdf");
    const autoTable = (await import("jspdf-autotable")).default;

    const doc   = new jsPDF();
    const pageW = doc.internal.pageSize.getWidth();
    const pageH = doc.internal.pageSize.getHeight();
    const L     = 18;
    const R     = pageW - 18;

    // ── HEADER: logo square ──
    doc.setFillColor(15, 23, 42);
    doc.roundedRect(L, 12, 11, 11, 1.5, 1.5, "F");
    // lines in logo
    [[L+2.5,15.5,8.5],[L+2.5,18.2,8.5],[L+2.5,20.8,5.5]].forEach(([x,y,w])=>{
      doc.setFillColor(255,255,255);
      doc.rect(x,y,w,1.5,"F");
    });

    // Company name
    doc.setTextColor(15, 23, 42);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(13);
    doc.text(CO_NAME, L + 14, 19.5);

    // Company details
    doc.setFont("helvetica", "normal");
    doc.setFontSize(7.5);
    doc.setTextColor(100, 110, 125);
    doc.text(CO_CITY,  L + 14, 25);
    doc.text(CO_PHONE, L + 14, 30);
    doc.text(CO_EMAIL, L + 14, 35);

    // Invoice title – top right
    const invNum = invoice.invoiceNumber.replace("INV-", "");
    doc.setFont("helvetica", "bold");
    doc.setFontSize(22);
    doc.setTextColor(15, 23, 42);
    doc.text(`INVOICE`, R, 22, { align: "right" });
    doc.setFontSize(28);
    doc.setTextColor(15, 23, 42);
    doc.text(`#${invNum}`, R, 34, { align: "right" });

    // separator
    doc.setDrawColor(210, 215, 225);
    doc.setLineWidth(0.5);
    doc.line(L, 42, R, 42);

    // ── BILLING SECTION ──
    const colR = pageW / 2 + 8;
    const y0   = 50;

    // Left: Billed To
    doc.setFontSize(7);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(120, 130, 145);
    doc.text("BILLED TO", L, y0);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(10);
    doc.setTextColor(15, 23, 42);
    doc.text(invoice.clientName, L, y0 + 6.5);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8.5);
    doc.setTextColor(90, 100, 115);
    doc.text(invoice.clientAddress, L, y0 + 13);

    // Right: Invoice meta
    const metaRows: [string, string][] = [
      ["INVOICE NUMBER", invoice.invoiceNumber],
      ["DATE ISSUED",    new Date(invoice.createdAt).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" })],
      ["DUE DATE",       (() => { const d = new Date(invoice.createdAt); d.setDate(d.getDate()+30); return d.toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" }); })()],
    ];
    let mY = y0;
    metaRows.forEach(([label, val], i) => {
      doc.setFontSize(7);
      doc.setFont("helvetica", "normal");
      doc.setTextColor(120, 130, 145);
      doc.text(label, colR, mY + (i === 0 ? 0 : 0));
      doc.setFontSize(9);
      doc.setFont(i === 0 ? "helvetica" : "helvetica", i === 0 ? "bold" : "normal");
      doc.setTextColor(15, 23, 42);
      doc.text(val, colR, mY + 5.5);
      mY += 14;
    });

    // separator
    doc.setDrawColor(210, 215, 225);
    doc.setLineWidth(0.4);
    doc.line(L, 90, R, 90);

    // ── ITEMS TABLE ──
    const tableData = invoice.items.map(item => [
      item.description,
      item.rate.toFixed(2),
      (item.amount ?? item.rate).toFixed(2),
    ]);

    autoTable(doc, {
      startY: 96,
      head: [["Description", "Rate", "Amount"]],
      body: tableData,
      theme: "plain",
      headStyles: {
        fillColor: [243, 244, 246],
        textColor: [100, 110, 125],
        fontSize: 7.5,
        fontStyle: "bold",
        cellPadding: { top: 6, bottom: 6, left: 5, right: 5 },
        lineColor: [210, 215, 225],
        lineWidth: { bottom: 0.5, top: 0.5, left: 0, right: 0 },
      },
      bodyStyles: {
        fontSize: 8.5,
        textColor: [30, 38, 50],
        lineColor: [225, 230, 238],
        lineWidth: { bottom: 0.3, top: 0, left: 0, right: 0 },
        cellPadding: { top: 6, bottom: 6, left: 5, right: 5 },
      },
      alternateRowStyles: { fillColor: [249, 250, 251] },
      columnStyles: {
        0: { halign: "left",  cellWidth: "auto" },
        1: { halign: "right", cellWidth: 30, font: "courier" },
        2: { halign: "right", cellWidth: 34, font: "courier", fontStyle: "bold" },
      },
      margin: { left: L, right: 18 },
    });

    const finalY: number = (doc as any).lastAutoTable?.finalY ?? 160;

    // ── TOTALS BLOCK ──
    const bX  = R - 72;
    const tY  = finalY + 10;

    doc.setDrawColor(210, 215, 225);
    doc.setLineWidth(0.4);
    doc.line(bX, tY, R, tY);

    doc.setFontSize(8.5);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(90, 100, 115);
    doc.text("SubTotal:", bX, tY + 8);

    doc.setFont("courier", "bold");
    doc.setFontSize(9.5);
    doc.setTextColor(15, 23, 42);
    doc.text(total.toFixed(2), R, tY + 8, { align: "right" });

    doc.setFontSize(7.5);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(120, 130, 145);
    doc.text("AED", R, tY + 15, { align: "right" });

    doc.setDrawColor(210, 215, 225);
    doc.line(bX, tY + 20, R, tY + 20);

    // ── FOOTER ──
    doc.setFontSize(7);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(170, 178, 190);
    doc.text(`Made with ${CO_NAME} · Digital Invoice Solutions`, pageW / 2, pageH - 10, { align: "center" });

    doc.save(`${invoice.invoiceNumber}.pdf`);
  }, [invoice, total]);

  /* ── ON-SCREEN PREVIEW ── */
  const invoiceNum = invoice.invoiceNumber.replace("INV-", "");
  const issuedDate = new Date(invoice.createdAt).toLocaleDateString("en-GB", {
    day: "numeric", month: "long", year: "numeric",
  });
  const dueDate = new Date(invoice.createdAt);
  dueDate.setDate(dueDate.getDate() + 30);
  const dueDateStr = dueDate.toLocaleDateString("en-GB", {
    day: "numeric", month: "long", year: "numeric",
  });

  return (
    <div className="max-w-4xl mx-auto space-y-5">
      {/* Toolbar */}
      <div className="flex items-center justify-between gap-3 flex-wrap animate-slide-down">
        <div className="flex items-center gap-3">
          <Button
            variant="ghost"
            size="icon"
            onClick={onBack}
            className="rounded-lg hover:bg-muted transition-colors"
            data-testid="button-back-to-editor"
          >
            <ArrowLeft className="w-4 h-4" />
          </Button>
          <div>
            <h2
              className="text-lg font-bold tracking-tight text-foreground"
              data-testid="text-preview-title"
            >
              Invoice Preview
            </h2>
            <p className="text-xs font-label uppercase tracking-wider text-muted-foreground">
              {invoice.invoiceNumber} &middot; {invoice.clientName}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            onClick={onNewScan}
            className="gap-2 transition-all hover:shadow-sm"
            data-testid="button-new-scan-preview"
          >
            <Plus className="w-4 h-4" />
            New Scan
          </Button>
          <Button
            onClick={generatePDF}
            className="gap-2 transition-all hover:shadow-md"
            data-testid="button-generate-pdf"
          >
            <Download className="w-4 h-4" />
            Download PDF
