                    {invoice.status}
                  </span>
                </td>

                {/* Amount */}
                <td className="px-5 py-4 text-right">
                  <span
                    className="text-sm font-mono font-bold text-foreground tabular-nums"
                    data-testid={`text-invoice-total-${invoice.id}`}
